package com.earthtrip.expense.adapter.in.web.api.v1.trips.by_trip_id.expenses.by_expense_id.splits;import com.earthtrip.expense.application.port.in.ExpenseUseCase;import com.earthtrip.sharedkernel.security.CurrentActor;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/trips/{tripId}/expenses/{expenseId}/splits") class ExpenseSplitsController{private final ExpenseUseCase useCase;private final CurrentActor actor;ExpenseSplitsController(ExpenseUseCase u,CurrentActor a){useCase=u;actor=a;}@PostMapping @ResponseStatus(HttpStatus.CREATED) List<ExpenseUseCase.ExpenseResult> post(@PathVariable UUID tripId,@PathVariable UUID expenseId,@Valid @RequestBody SplitMutation r){return useCase.split(tripId,expenseId,actor.requireUserId(),r.baseVersion(),r.parts().stream().map(p->new ExpenseUseCase.SplitPart(p.requestId(),p.title(),p.categoryCode(),p.amountMinor(),p.payerContributions(),p.participantShares())).toList());}}
record SplitMutation(@Min(0)long baseVersion,@Size(min=2)List<@Valid SplitPartMutation>parts){}record SplitPartMutation(@NotNull UUID requestId,@NotBlank String title,@NotBlank String categoryCode,@Positive long amountMinor,@NotEmpty Map<UUID,@PositiveOrZero Long>payerContributions,@NotEmpty Map<UUID,@PositiveOrZero Long>participantShares){}
